public record Sale(string Product, string Region, decimal Price, int Quantity);

public static class Solution
{
    public static decimal Revenue(IEnumerable<Sale> sales) => sales.Sum(s => s.Price * s.Quantity);

    public static List<string> TopProducts(IEnumerable<Sale> sales, int n) =>
        sales.GroupBy(s => s.Product)
             .Select(g => (Product: g.Key, Units: g.Sum(s => s.Quantity)))
             .OrderByDescending(p => p.Units)
             .ThenBy(p => p.Product, StringComparer.Ordinal)
             .Take(n)
             .Select(p => p.Product)
             .ToList();

    public static Dictionary<string, decimal> RevenueByRegion(IEnumerable<Sale> sales) =>
        sales.GroupBy(s => s.Region).ToDictionary(g => g.Key, g => g.Sum(s => s.Price * s.Quantity));

    public static string? BiggestSale(IEnumerable<Sale> sales) =>
        sales.MaxBy(s => s.Price * s.Quantity) is Sale s ? $"{s.Product} in {s.Region}" : null;

    public static List<string> RegionsSelling(IEnumerable<Sale> sales, string product) =>
        sales.Where(s => s.Product == product).Select(s => s.Region).Distinct().Order(StringComparer.Ordinal).ToList();
}

