var sales = new List<Sale>
{
    new("tea", "north", 2.50m, 10),
    new("cake", "north", 4.00m, 3),
    new("tea", "south", 2.50m, 4),
    new("mug", "south", 8.00m, 5),
    new("cake", "east", 4.00m, 11),
    new("mug", "north", 8.00m, 1),
};

Test("revenue", () =>
{
    CheckEq(Revenue(sales), 25m + 12m + 10m + 40m + 44m + 8m);
    CheckEq(Revenue(new List<Sale>()), 0m);
});

Test("top products", () =>
{
    CheckEq(TopProducts(sales, 2), new[] { "cake", "tea" });
    CheckEq(TopProducts(sales, 10), new[] { "cake", "tea", "mug" });
    CheckEq(TopProducts(sales, 0).Count, 0);
});

Test("revenue by region", () =>
{
    var r = RevenueByRegion(sales);
    CheckEq(r.Count, 3);
    CheckEq(r["north"], 45m);
    CheckEq(r["south"], 50m);
    CheckEq(r["east"], 44m);
});

Test("biggest sale and regions", () =>
{
    CheckEq(BiggestSale(sales), "cake in east");
    CheckEq(BiggestSale(new List<Sale>()), null);
    CheckEq(RegionsSelling(sales, "mug"), new[] { "north", "south" });
    CheckEq(RegionsSelling(sales, "pen").Count, 0);
});

